#!/usr/bin/env node
// Regenerates modules/slides/domain/structured/tailwind-color-palette.generated.ts
// from the installed `tailwindcss` package's own default color export
// (`tailwindcss/colors`) - a stable, versioned JS export Tailwind ships
// specifically for programmatic consumption, not a re-derivation from CSS
// output. Run after upgrading the `tailwindcss` dependency:
//
//   node scripts/generate-tailwind-color-palette.mjs
//
// modules/slides/domain/structured/tailwind-color-palette.drift.test.ts
// fails if the committed generated file no longer matches what this script
// would produce, so a Tailwind upgrade that changes default color values
// cannot silently go unnoticed.

import { writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

import colors from "tailwindcss/colors";

const require = createRequire(import.meta.url);
const tailwindPackageJson = require("tailwindcss/package.json");

const OUTPUT_PATH = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../modules/slides/domain/structured/tailwind-color-palette.generated.ts",
);

// `inherit` resolves to the literal string "inherit", which is a valid but
// practically useless whitelist entry for a text color (it means "same as
// parent," meaningless without a parent style context here) - every other
// top-level string entry (current/transparent/black/white) and every
// family/shade pair becomes one `text-{key}` / `text-{family}-{shade}`
// whitelist entry.
export function buildTailwindTextColorPalette(colorExport) {
  const entries = {};
  for (const [key, value] of Object.entries(colorExport)) {
    if (key === "inherit") continue;
    if (typeof value === "string") {
      entries[`text-${key}`] = value;
      continue;
    }
    for (const [shade, shadeValue] of Object.entries(value)) {
      entries[`text-${key}-${shade}`] = shadeValue;
    }
  }
  return entries;
}

function renderModule(entries, sourceVersion) {
  const lines = Object.entries(entries)
    .map(([key, value]) => `  ${JSON.stringify(key)}: ${JSON.stringify(value)},`)
    .join("\n");
  return `// AUTO-GENERATED by scripts/generate-tailwind-color-palette.mjs - do not edit by hand.
// Regenerate with \`node scripts/generate-tailwind-color-palette.mjs\` after
// upgrading the \`tailwindcss\` dependency. tailwind-color-palette.drift.test.ts
// fails if this file no longer matches what the installed tailwindcss
// package would produce.

export const TAILWIND_COLOR_PALETTE_SOURCE_VERSION = ${JSON.stringify(sourceVersion)};

export const TAILWIND_DEFAULT_TEXT_COLORS: Readonly<Record<string, string>> = {
${lines}
};
`;
}

function main() {
  const palette = buildTailwindTextColorPalette(colors);
  writeFileSync(OUTPUT_PATH, renderModule(palette, tailwindPackageJson.version));
  console.log(`Wrote ${Object.keys(palette).length} color entries (tailwindcss@${tailwindPackageJson.version}) to ${OUTPUT_PATH}`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}
